INSERT INTO system.company_setting (id, singleton, company_name_en, company_name_ar, cr_number, vat_id, vat_enabled, vat_percentage, vat_certificate_url, default_currency, currency_decimals, address_en, address_ar, phone, country_code, mobile_number, whatsapp_phone, whatsapp_country_code, whatsapp_mobile_number, email, website, instagram_url, linkedin_url, youtube_url, map_url, bank_name, bank_iban, bank_account_number, bank_swift, time_zone, logo_url, dark_logo_url, full_logo_url, dark_full_logo_url, icon_url, dark_icon_url, stamp_url, signature_url, document_header_url, document_footer_url, payment_terms_days, invoice_prefix, invoice_next_number, receipt_prefix, receipt_next_number, ceo_name_en, ceo_name_ar, ceo_title_en, ceo_title_ar, ceo_quote_en, ceo_quote_ar, tagline_en, tagline_ar, about_text_en, about_text_ar, mission_en, mission_ar, vision_en, vision_ar, terms_en, terms_ar, rules_en, rules_ar, founded_year, city, country, primary_language, business_activity, default_discount_limit_percent, quotations_always_need_approval, theme, setup_completed_at, website_domain, admin_domain, updated_at) VALUES ('c0000000-0000-0000-0000-000000000001', 1, 'Seamark Freight & Customs W.L.L.', 'سيمارك للشحن والتخليص الجمركي ذ.م.م', 'CR-114320-1', '200011432000002', true, 10, '/api/files/brand/stamp.png', 'BHD', 3, 'Warehouse 14, KBSP Logistics Zone, Hidd', 'مستودع 14، المنطقة اللوجستية بميناء خليفة، الحد', '+97317671190', 'BH', '17671190', '+97339671190', 'BH', '39671190', 'ops@seamarkfreight.bh', 'https://seamarkfreight.bh', 'https://instagram.com/seamark-freight', 'https://linkedin.com/company/seamark-freight', 'https://youtube.com/@seamark-freight', 'https://maps.google.com/?q=Khalifa%20Bin%20Salman%20Port%2C%20Bahrain', 'Standard Chartered Bahrain', 'BH30SCBL00000014320001', '0014320001', 'SCBLBHBX', 'Asia/Bahrain', '/api/files/brand/logo-dark.png', '/api/files/brand/logo-light.png', '/api/files/brand/logo-dark.png', '/api/files/brand/logo-light.png', '/api/files/brand/icon-light.png', '/api/files/brand/icon-dark.png', '/api/files/brand/stamp.png', '/api/files/brand/signature.png', '/api/files/media/banners/banner-01.png', '/api/files/media/banners/banner-02.png', 30, 'SMF', 150, 'RCT', 150, 'Adel Al-Shirawi', 'عادل الشيراوي', 'Director of Operations', 'مدير العمليات', 'Precision delivery from Khalifa Bin Salman Port across the GCC.', 'التميز التشغيلي من Khalifa Bin Salman Port إلى جميع أسواق الخليج.', 'Sea-Air Freight Forwarding, Bonded Warehousing & Customs', 'الشحن البحري والجوي والتخزين الجمركي والتخليص', 'B2B freight forwarding and bonded warehousing operator handling customs clearance and GCC cross-border fleet distribution.', 'شركة شحن وتخزين جمركي تدير التخليص الجمركي والتوزيع البري عبر دول الخليج.', 'Deliver benchmark logistics services with clear bilingual accountability.', 'تقديم خدمات موثوقة ثنائية اللغة وفق أعلى معايير الجودة والالتزام.', 'To lead Bahrain''s enterprise ecosystem in logistics innovation.', 'أن نكون الشريك المرجعي الأول لقطاع الأعمال في مملكة البحرين والخليج.', 'Invoices are payable within 30 calendar days in BHD. Late balances accrue documented reminders.', 'تستحق الفواتير خلال 30 يوماً بعملة BHD وفق شروط العقد المعتمد.', '10% VAT compliant with Bahrain NBR e-invoicing guidelines; signed approvals logged digitally.', 'تطبق ضريبة القيمة المضافة 10% وفق متطلبات الجهاز الوطني للإيرادات.', 2012, 'Khalifa Bin Salman Port', 'BH', 'ar', 'logistics', 15, false, '{"primary":"#0C4A6E","accent":"#0284C7","radius":"sm","defaultMode":"light","fonts":{"body":{"kind":"google","family":"Inter"},"heading":{"kind":"google","family":"Inter"}}}'::jsonb, '2026-01-01T00:00:00Z', 'seamarkfreight.bh', 'admin.seamarkfreight.bh', now()) ON CONFLICT (id) DO NOTHING;
