INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-1', 'pcat-cms-1', 'seamark-freight-case-1', 'Hidd Bonded Pharma Cold-Store Commissioning', 'تشغيل مستودع الأدوية المبرد بمنطقة الحد', 'Al-Jazeera Gulf Holdings W.L.L.', 2025, 'Delivered for Al-Jazeera Gulf Holdings W.L.L. across Khalifa Bin Salman Port with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة الجزيرة الخليجية القابضة في Khalifa Bin Salman Port وفق أعلى معايير الجودة والالتزام.', 130, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://seamarkfreight.bh/work/seamark-freight-case-1', 'Khalifa Bin Salman Port, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-1', 'seamark-freight-2026-outlook', 'Seamark Freight 2026 GCC Market Outlook & Benchmarks', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — سيمارك للشحن', 'Key operational benchmarks, real metrics, and 2026 guidance from Seamark Freight in Khalifa Bin Salman Port.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من سيمارك للشحن في Khalifa Bin Salman Port.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"B2B freight forwarding and bonded warehousing operator handling customs clearance and GCC cross-border fleet distribution. Focusing on Import/Export Customs Clearance, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"شركة شحن وتخزين جمركي تدير التخليص الجمركي والتوزيع البري عبر دول الخليج. من خلال خدمة التخليص الجمركي للاستيراد والتصدير نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>B2B freight forwarding and bonded warehousing operator handling customs clearance and GCC cross-border fleet distribution.</p><p>Focusing on <strong>Import/Export Customs Clearance</strong>, our Khalifa Bin Salman Port specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>شركة شحن وتخزين جمركي تدير التخليص الجمركي والتوزيع البري عبر دول الخليج.</p><p>من خلال خدمة <strong>التخليص الجمركي للاستيراد والتصدير</strong>، يعمل فريقنا في Khalifa Bin Salman Port على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-01.png', 'Seamark Freight 2026 GCC Market Outlook & Benchmarks | Seamark Freight', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — سيمارك للشحن | سيمارك للشحن', 'Executive guide by Seamark Freight covering Import/Export Customs Clearance benchmarks in Bahrain.', 'دليل تنفيذي من سيمارك للشحن حول معايير التخليص الجمركي للاستيراد والتصدير في البحرين.', 'Insights', '{"logistics","insights","Khalifa Bin Salman Port","2026"}'::text[], 'Hana Yousef', 'draft', now() - interval '6 days', true, now() - interval '6 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-1', 'How quickly can Seamark Freight initiate a Import/Export Customs Clearance engagement?', 'كم يستغرق بدء تنفيذ خدمة التخليص الجمركي للاستيراد والتصدير لدى سيمارك للشحن؟', 'Discovery and kickoff begin within 48 hours of quotation sign-off, with a dedicated lead assigned in Khalifa Bin Salman Port.', 'يبدأ التخطيط والتنفيذ خلال 48 ساعة من اعتماد عرض السعر مع تعيين مدير حساب مخصص في Khalifa Bin Salman Port.', 'services', false, 1, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-2', 'pcat-cms-2', 'seamark-freight-case-2', 'Causeway 4-Hour Fast-Lane Produce Shuttle', 'خط النقل السريع عبر جسر الملك فهد في 4 ساعات', 'Bahrain Bay Hospitality Group', 2026, 'Delivered for Bahrain Bay Hospitality Group across Khalifa Bin Salman Port with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة خليج البحرين للضيافة في Khalifa Bin Salman Port وفق أعلى معايير الجودة والالتزام.', 1140, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://seamarkfreight.bh/work/seamark-freight-case-2', 'Khalifa Bin Salman Port, Bahrain') ON CONFLICT (id) DO NOTHING;
